"""Bloody slot: ВСЕ числа и решения игры в одном месте (стадия 1: поле, выплаты, веса). Правила и таблица выплат из задания владельца
(bloody-slot-prompt.md), всё остальное: допущения ведущего, помечены «ДОПУЩЕНИЕ» и меняются здесь без правки кода движка.

Деньги: в движке 1 ставка = UNITS_PER_BET (100) единиц, поэтому выплаты вроде 0.05× ставки целые; в фишках выплата = единицы * ставка // 100
(округление вниз, один раз на раунд). Максимум раунда 16161× ставки."""

UNITS_PER_BET = 100
MAX_WIN_BETS = 16161                     # из задания: раунд заканчивается на потолке
REELS = 5                                # барабанов (слева направо)
WORKING_ROWS = 4                         # ДОПУЩЕНИЕ: рабочих рядов 4 (1024 способа), плюс закреплённый нижний ряд Wild; 5 даёт поле 5-5-5-5-5 (3125 способов)
MIN_WIN_LENGTH = 3                       # минимум барабанов в комбинации (с первого)
MIN_REAL_REELS = 3                       # ДОПУЩЕНИЕ (правила молчат): в комбинации не меньше стольких барабанов с НАСТОЯЩИМ символом или Wild рабочих рядов;
                                         # закреплённый ряд Wild только подставляется. Без этого уже два открытых Wild превращают любой символ третьего барабана
                                         # в вечный выигрыш (цепочка каскадов бесконечна, закреплённые Wild не исчезают); 3 = минимальная длина выигрыша: закреплённые Wild
                                         # заполняют пропуски и умножают способы, но комбинацию не создают
MIN_REAL_BY_LEVEL = (3, 3, 4, 5, 5, 5)   # ДОПУЩЕНИЕ (подгонка RTP): то же требование в основной игре и Candle Spins по уровню полоски 0..5. С каждым уровнем
                                         # убирается низкий символ и открывается Wild, поле уплотняется: без этого спин уровня 4 стоит ~90 ставок
MAX_CASCADE_STEPS = 60                   # защита от бесконечной цепочки (по весам недостижима)

HIGH = ("H1", "H2", "H3", "H4", "H5")    # портреты существ (ведьма, волк, ...): H1 дороже всех
MID = ("M1", "M2", "M3", "M4", "M5")     # блёклые портреты
LOW = ("L1", "L2", "L3", "L4", "L5")     # оккультные знаки на плитках
WILD = "W"                               # череп с канделябрами
SCATTER = "S"
PAY_SYMBOLS = HIGH + MID + LOW

# выплата за 3 / 4 / 5 барабанов в долях ставки (из задания), хранится в единицах (×100)
_PAY = {
    "H1": (5.00, 3.00, 1.50), "H2": (4.50, 2.50, 1.25), "H3": (4.00, 2.00, 1.00), "H4": (3.00, 1.50, 0.75), "H5": (2.00, 1.00, 0.50),
    "M1": (1.20, 0.80, 0.45), "M2": (1.10, 0.70, 0.40), "M3": (0.90, 0.60, 0.35), "M4": (0.70, 0.50, 0.30), "M5": (0.60, 0.40, 0.25),
    "L1": (0.40, 0.30, 0.20), "L2": (0.30, 0.25, 0.15), "L3": (0.25, 0.20, 0.10), "L4": (0.20, 0.15, 0.05), "L5": (0.15, 0.10, 0.05),
}                                        # в таблице задания порядок «5 / 4 / 3»: здесь (5, 4, 3) → ниже переводим в словарь по длине
PAYTABLE_UNITS = {sym: {5: round(v[0] * UNITS_PER_BET), 4: round(v[1] * UNITS_PER_BET), 3: round(v[2] * UNITS_PER_BET)} for sym, v in _PAY.items()}
WILD_PAY_UNITS = {5: 5 * UNITS_PER_BET}  # Wild платит 5.00 только за 5 в ряд (экран заполнен Wild)

# ДОПУЩЕНИЕ (стадия 1, предварительно; подбираются симулятором на стадии 4): веса символов при падении новых, Scatter и Wild в рабочих рядах
SYMBOL_WEIGHTS = {
    "H1": 0, "H2": 0, "H3": 0, "H4": 0, "H5": 0,        # высокие символы в начале раунда не падают: они появляются только как улучшение средних (см. MID_TRANSFORM_ORDER)
    "M1": 10, "M2": 10, "M3": 11, "M4": 11, "M5": 12,
    "L1": 14, "L2": 14, "L3": 15, "L4": 15, "L5": 16,
}
WILD_WEIGHT = 0.3                        # Wild в рабочих рядах основной игры (подгонка RTP)
SCATTER_WEIGHT = 2.1                    # Scatter в основной игре (+10 очков полоски за каждый); подгонка частоты бонуса (цель как в оригинале: ~1 раунд из 18)

# ставки: лестница одна на все режимы (фишки, ставка не меньше 20, чтобы выплаты 0.05× были целыми фишками)
BET_LADDER = (20, 40, 100, 200, 400, 1000, 2000, 4000, 10000, 20000, 40000, 100000, 200000, 400000, 1000000)

# ---- Ritual bar (этап 2). Уровень = число пройденных порогов (0..5): пройденный порог N открывает Wild номер N нижнего ряда
BAR_THRESHOLDS = (20, 30, 40, 60, 80)    # из задания: очков для перехода на уровень 1..5, излишек переносится
BAR_MAX_LEVEL = len(BAR_THRESHOLDS)
BAR_POINTS_MID = 1                       # средний символ в выигрыше: +1 за каждую взорванную ячейку
BAR_POINTS_HIGH = 2                      # высокий символ: +2
BAR_POINTS_SCATTER = 10                  # Scatter: +10 за каждый (начисляется на этапе 3 вместе с запуском функций)
# ДОПУЩЕНИЕ (§3.2 задания): на каждом новом уровне исчезает самый дешёвый из оставшихся низких символов (L5, потом L4, ...), а самый дорогой из оставшихся
# средних превращается в высокий (M1 → H1, M2 → H2, ...): на поле ячейки меняют вид, в таблице падения вес среднего переходит высокому
LOW_REMOVE_ORDER = ("L5", "L4", "L3", "L2", "L1")
MID_TRANSFORM_ORDER = ("M5", "M4", "M3", "M2", "M1")   # решение владельца: первым улучшается ворон (M5 → H5), потом змея, козёл, волк, ведьма; прежний средний символ пропадает полностью
MID_TO_HIGH = {"M1": "H1", "M2": "H2", "M3": "H3", "M4": "H4", "M5": "H5"}

# ---- бонусные режимы, Scatter, xSplit, Sticky Wild (этап 3)
CANDLE_SPINS_PER_LEVEL = 2               # из задания: +2 Candle Spins за каждый новый уровень полоски
CANDLE_MAX_LEVEL = 4                     # ... до 4-го уровня включительно
REIGN_SPINS = 6                          # +6 Reign of Terror Spins при достижении последнего уровня
REIGN_SCATTER_SPINS = 1                  # Scatter в Reign даёт +1 спин
CANDLE_CANCELLED_ON_REIGN = True         # ДОПУЩЕНИЕ: оставшиеся Candle Spins сгорают при запуске Reign (полоска убирается, режимы не смешиваются)
MAX_SPINS_PER_ROUND = 300                # защита от бесконечной серии (по весам недостижима)
SCATTER_REPLACE = True                   # Scatter исчезает сразу после начисления очков или спина (на его месте падают новые символы)

XDAGGER = "XD"                           # Dagger: разделяет свой ряд
XGUILLOTINE = "XG"                       # Guillotine: разделяет все символы под собой на своём барабане
XSPLIT_FACTOR = 2                        # из задания: каждое разделение удваивает число способов ячейки (множитель ×2)
XSPLIT_MAX_MULT = 32                     # из задания: итоговый множитель ячейки не больше ×32
XSPLIT_WEIGHT = 0.02                     # вес каждого из двух xSplit-символов в основной игре и Candle Spins (подгонка RTP)
XSPLIT_MIN_LEVEL = 4                     # ДОПУЩЕНИЕ: в основной игре и Candle Spins xSplit падают с этого уровня полоски; в Reign всегда
REIGN_WILDS_OPEN = 0                     # ДОПУЩЕНИЕ: в Reign и спине xBet 2 закреплённый ряд Wild не используется (иначе пять Wild на каждом спине дают выплаты в сотни ставок)
REIGN_ROWS = 5                           # из гайда: в Reign of Terror Spins поле 5×5 только из высоких символов (нижний ряд Wild становится обычным рядом)

# ---- хранение раунда (этап 3)
IDLE_SECONDS = 7 * 86400                 # из задания: незавершённый раунд закрывается через 7 дней без действий с выплатой накопленного
XP_LOSE_X1000 = {None: 581, "xbet1": 365, "xbet2": 280, "gibbet": 223, "reign": 0, "lucky": 118}   # опыт = цена * доля раундов без выплаты (тысячные, по симулятору v2, docs/bloody_slot_rtp.json)

# ---- покупки функций (этап 4). Цена в единицах (100 = одна ставка); RTP каждой покупки = средний выигрыш / цена, цены подгоняются симулятором
BUY_COST_UNITS = {"gibbet": 10000, "reign": 50000, "xbet1": 250, "xbet2": 6600, "lucky": 24000}   # цены как в оригинале (гайд владельца): Виселица 100×, Reign 500×, xBet 1 2,5×, xBet 2 66×, Lucky Draw 240×
BUY_KINDS = tuple(BUY_COST_UNITS)
GIBBET_LEVEL = 3                         # Виселица: полоска сразу на уровне 3 (Wild 1-3 открыты, символы изменены как после трёх переходов)
GIBBET_CANDLE_SPINS = 6                  # ... и +6 Candle Spins
GIBBET_UPGRADED_CELLS = 3                # ... и три низких или средних символа первого поля заменяются тремя высокими
REIGN_BUY_SPINS = 10                     # покупка Reign of Terror Spins: сразу 10 бесплатных спинов
# Lucky Draw (решение владельца): случайно запускается бонус; доля, уровень полоски, бонусные спины. Уровень 5 = Reign of Terror Spins
LUCKY_DRAW = ((0.4, 3, 6), (0.4, 4, 8), (0.2, 5, 6))
BONUS_START_BUYS = ("gibbet", "lucky")     # покупки, которые начинаются сразу с бесплатных спинов (без стартового спина)
XBET1_START_LEVEL = 1                    # xBet 1: всегда стартует с уровня 1 (Wild 1 открыт)
XBET1_POINT_MULT = 1.338                   # ДОПУЩЕНИЕ: во сколько раз быстрее полоска копит очки у Ритуального буста xBet 1; выше 2 RTP по цене 2,5 ставки недостижим (см. docs/BLOODY_SLOT.md)
XBET2_LEVEL = 5                          # xBet 2: спин на уровне 5 (все Wild открыты, поле из высоких) с гарантированными Dagger и Guillotine
# ---- ручки подгонки RTP (этап 4): задание не фиксирует частоты, потолки цепочек и минимальную длину комбинации в бонусах; подбираются симулятором (tools/simulate_bloody_slot.py)
MAX_CASCADES = {"base": 0, "candle": 3, "reign": 1, "xbet2": 1}      # потолок каскадов за спин по режимам (0 = без потолка); подгонка RTP (см. docs/BLOODY_SLOT.md)
WIN_MIN_LENGTH = {"base": 3, "candle": 3, "reign": 3, "xbet2": 5}    # минимум барабанов в комбинации по режимам (в спине xBet 2 нужны все пять: гарантированные xSplit иначе слишком щедры)
WILD_WEIGHT_CANDLE = 0.3                 # вес Wild (прилипающих) в Candle Spins
WILD_WEIGHT_REIGN = 0.005                # вес Wild в Reign of Terror Spins и спине xBet 2
SCATTER_WEIGHT_REIGN = 0.0021            # вес Scatter в Reign (+1 спин)
XSPLIT_WEIGHT_REIGN = 0.0346             # вес каждого xSplit-символа в Reign; основная ручка RTP покупки Reign (500×, поле 5×5)
XSPLIT_WEIGHT_XBET2 = 0.0008             # вес каждого xSplit-символа в спине xBet 2 (кроме двух гарантированных); основная ручка RTP xBet 2
XBET2_WEIGHTS = {"H1": 1, "H2": 1, "H3": 1, "H4": 1, "H5": 1}        # веса высоких символов в спине xBet 2
REIGN_WEIGHTS = {"H1": 1, "H2": 1, "H3": 1, "H4": 1, "H5": 1}        # веса высоких символов в Reign (поле только из высоких)
LEVEL_MID_SCALE = (1.0, 1.049, 1.049, 1.049, 1.049, 1.0)    # множитель веса средних символов по уровню полоски 0..5 (подгонка RTP симулятором)
LEVEL_HIGH_SCALE = (1.0, 1.049, 1.049, 1.049, 1.049, 1.0)   # множитель веса улучшенных высоких символов (относительно веса среднего, из которого они вышли) по уровню 0..5; подгонка RTP
MAX_CASCADES_BY_LEVEL = (6, 2, 1, 1, 1, 1)  # потолок каскадов за спин основной игры и Candle Spins по текущему уровню полоски 0..5 (0 = без потолка): чем выше уровень, тем плотнее поле
SCATTER_WEIGHT_CANDLE = (0.75, 5.275, 5.275, 3.496, 2.958, 0.75)   # вес Scatter в Candle Spins по уровню полоски 0..5 (+10 очков за каждый): чем выше, тем чаще полоска доходит до Reign.
                                         # Уровни 1-2: RTP основной игры и хвост ×100; уровень 3: Виселица; уровень 4: Lucky Draw (подгонка вместе)
